(()=>{
const storage='cicluz-organogram-positions-v1';
const prior=showConfig;showConfig=function(type,origin){if(type==='organograma')return showOrganogram(origin);return prior(type,origin)};
function showOrganogram(origin='Gestão de Pessoas'){
 const view=document.getElementById('sector-view'),box=document.getElementById('sector-content');view.classList.remove('financial-groups','financial-hierarchy','account-orange');view.style.setProperty('--menu-accent','#7c3aed');view.querySelector('.panel').style.setProperty('--panel-color','#7c3aed');view.querySelector('.panel').style.setProperty('--panel-text','#5520ad');view.querySelectorAll('.view-alphabetize,.financial-expand-all,.location-tool,.organogram-tool').forEach(e=>e.remove());document.getElementById('sector-title').textContent='Organograma';document.getElementById('sector-path').textContent='Gestão de Pessoas / Organograma';document.getElementById('crumb').textContent='Gestão de Pessoas / Organograma';setSectorBack(()=>openSection(sections[6][0],'Gestão de Pessoas','people-settings','#7c3aed'));box.replaceChildren();
 let data={nodes:[],versions:[]};try{const saved=JSON.parse(localStorage.getItem(storage)||'null');if(saved&&Array.isArray(saved.nodes))data={nodes:saved.nodes,versions:saved.versions||[]}}catch{}
 let editing=true;const closed=new Set();const allNodes=()=>{const a=[];const visit=nodes=>nodes.forEach(n=>{a.push(n);visit(n.children||[])});visit(data.nodes);return a};
 const button=(text,fn,cls='btn secondary')=>{const b=document.createElement('button');b.type='button';b.className=cls;b.textContent=text;b.onclick=fn;return b};
 const tool=(label,path,fn)=>{const b=button('',fn,'shortcut-circle organogram-tool');b.title=label;b.setAttribute('aria-label',label);b.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="'+path+'"/></svg>';view.querySelector('.shortcut-actions').append(b);return b};
 tool('Atualizar organograma','M3 12a9 9 0 0 1 15.4-6.4L21 8M21 3v5h-5M21 12a9 9 0 0 1-15.4 6.4L3 16M3 21v-5h5',()=>showOrganogram(origin));const editTool=tool('Editar organograma','m4 20 4-.8L19 8l-3-3L5 16zM14.5 6.5l3 3',()=>{editing=!editing;editTool.setAttribute('aria-pressed',String(editing));render()});editTool.setAttribute('aria-pressed','true');
 tool('Expandir organograma','m5 9 7 7 7-7',()=>{closed.clear();render()});tool('Recolher organograma','m5 15 7-7 7 7',()=>{allNodes().forEach(n=>closed.add(n.id));render()});normalizeHeaderActions(view);
 const toolbar=document.createElement('div');toolbar.className='organogram-toolbar';const addRoot=button('+ Nova posição',()=>editor(null,data.nodes),'btn');const catalog=button('Cadastrar cargo',()=>showJobs());toolbar.append(addRoot,catalog);box.append(toolbar);
 const totals=document.createElement('div');totals.className='organogram-totals';box.append(totals);const note=document.createElement('p');note.className='organogram-note';note.textContent='Crie as caixas pelo + e selecione o cargo. Os nomes aparecerão quando o cadastro de colaboradores tiver o vínculo com o cargo.';box.append(note);const canvas=document.createElement('div');canvas.className='organogram-canvas organogram-planner organogram-mindmap';canvas.setAttribute('aria-label','Organograma de cargos e quadro previsto');box.append(canvas);
 function render(){canvas.replaceChildren();addRoot.hidden=!editing;const nodes=allNodes();const total=nodes.reduce((s,n)=>s+Number(n.quantity||0),0);totals.textContent=nodes.length+(nodes.length===1?' posição · ':' posições · ')+total+(total===1?' colaborador previsto':' colaboradores previstos');if(!nodes.length){const empty=document.createElement('div');empty.className='organogram-empty';const h=document.createElement('h3');h.textContent='Comece pela primeira posição';const p=document.createElement('p');p.textContent='Selecione um cargo e use o + para criar novas caixas abaixo, ligadas automaticamente por linhas.';empty.append(h,p,button('+ Começar organograma',()=>editor(null,data.nodes),'btn'));canvas.append(empty);return}const list=document.createElement('ul');list.className='organogram-branches';draw(data.nodes,list);canvas.append(list)}
 function draw(nodes,target){for(const node of nodes){const li=document.createElement('li');const card=document.createElement('div');card.className='organogram-card';const badge=document.createElement('span');badge.className='organogram-badge';badge.textContent=Array.from(node.jobName||'').slice(0,3).join('').toLocaleUpperCase('pt-BR');const copy=document.createElement('span');copy.className='organogram-position-copy';const name=document.createElement('b');name.textContent=node.jobName;const qty=document.createElement('small');qty.textContent='Sem colaboradores vinculados';copy.append(name,qty);if(node.label){const label=document.createElement('small');label.textContent=node.label;copy.append(label)}card.append(badge,copy);if(editing){const controls=document.createElement('span');controls.className='organogram-node-actions';const plus=button('+',()=>{closed.delete(node.id);editor(null,node.children,node)},'shortcut-circle');plus.title='Adicionar posição abaixo';plus.setAttribute('aria-label','Adicionar posição abaixo de '+node.jobName);const edit=button('',()=>editor(node,nodes),'shortcut-circle');edit.title='Editar posição';edit.setAttribute('aria-label','Editar posição '+node.jobName);edit.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m4 20 4-.8L19 8l-3-3L5 16zM14.5 6.5l3 3"/></svg>';controls.append(plus,edit);card.append(controls)}li.append(card);if(node.children.length){const details=document.createElement('details');details.open=!closed.has(node.id);details.ontoggle=()=>{details.open?closed.delete(node.id):closed.add(node.id)};const summary=document.createElement('summary');const count=descendantCount(node);summary.textContent=count+(count===1?' item':' itens');const children=document.createElement('ul');draw(node.children,children);details.append(summary,children);li.append(details)}target.append(li)}}
 function editor(node,pool,parent){
 const dialog=document.createElement('dialog');dialog.className='transfer-dialog organogram-editor';const form=document.createElement('form');const header=document.createElement('div');header.className='organogram-editor-header';const title=document.createElement('h3');title.textContent=node?'Editar posição':'Nova posição';const tools=document.createElement('span');tools.className='shortcut-actions';const close=button('',()=>dialog.close(),'shortcut-circle');close.title='Fechar';close.setAttribute('aria-label','Fechar cadastro de posição');close.innerHTML='<svg viewBox="0 0 24 24"><path d="m6 6 12 12M18 6 6 18"/></svg>';tools.append(close);header.append(title,tools);form.append(header);
 const field=(text,input)=>{const l=document.createElement('label');l.textContent=text;input.setAttribute('aria-label',text);l.append(input);form.append(l);return input};const entries=jobsCurrent().slice().sort((a,b)=>a.j.nome.localeCompare(b.j.nome,'pt-BR'));const search=field('Buscar cargo',document.createElement('input'));search.type='search';search.placeholder='Nome, categoria ou CBO';const job=field('Cargo',document.createElement('select'));job.required=true;let selection=entries.findIndex(e=>e.j.nome===node?.jobName&&String(e.j.cbo||'')===String(node?.cbo||''));const options=()=>{const old=job.value;job.replaceChildren(new Option('Selecione um cargo',''));entries.forEach((e,i)=>{if((e.j.nome+' '+e.j.categoria+' '+e.j.cbo).toLocaleLowerCase('pt-BR').includes(search.value.toLocaleLowerCase('pt-BR'))||String(i)===old)job.add(new Option(e.j.nome+(e.j.cbo?' · CBO '+e.j.cbo:''),String(i)))});if(selection>=0){job.value=String(selection);selection=-1}else job.value=old};options();search.oninput=options;if(parent){const context=document.createElement('p');context.textContent='Responde a: '+parent.jobName;form.append(context)}if(node&&!entries.some(e=>e.j.nome===node.jobName)){const notice=document.createElement('p');notice.textContent='O cargo original foi preservado nesta posição. Selecione um cargo do cadastro para atualizar.';form.append(notice)}const error=document.createElement('p');error.setAttribute('role','alert');form.append(error);const actions=document.createElement('div');actions.className='actions';const save=button('Salvar',()=>{},'btn');save.type='submit';actions.append(save,button('Cancelar',()=>dialog.close()));form.append(actions);form.onsubmit=e=>{e.preventDefault();const selected=entries[Number(job.value)],quantity=node?.quantity||1;if(job.value===''||!selected||!Number.isInteger(quantity)||quantity<1)return;const before=structuredClone(data);const values={jobKey:selected.key,jobName:selected.j.nome,cbo:selected.j.cbo||'',quantity,label:node?.label||''};if(node)Object.assign(node,values);else pool.push({id:crypto.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2),...values,children:[]});data.versions.push({date:new Date().toISOString(),nodes:before.nodes});try{localStorage.setItem(storage,JSON.stringify(data));dialog.close();render()}catch{data=before;error.textContent='Não foi possível salvar. Feche o cadastro e tente novamente.';save.disabled=true}};dialog.append(form);document.body.append(dialog);dialog.onclose=()=>dialog.remove();dialog.showModal();search.focus()
 }
 render();
}
})();
